uetas={requires="caught"},elementos={{t="goto",mapa=1427,x=40.5,y=35.7,modo="flecha",linea=21587},{t="nota",texto={en="Be careful as this quest can be VERY hard and risky. Don't be ashamed to skip it",es="Ten cuidado, ya que esta misión puede ser MUY difícil y arriesgada. No te avergüences de omitirla"},linea=21588,filtro={{"c:WARRIOR"},{"c:PRIEST"},{"c:ROGUE"}}},{t="nota",texto={en="Pull all 3 mobs with your pet and go loot the plans.",es="Tira de los 3 enemigos con tu mascota y ve a despojar los planos."},linea=21589,filtro={{"c:HUNTER"}}},{t="nota",texto={en="Pull both mobs with a Voidwalker or Succubus (seduce one of them) and go loot the plans.",es="Atrae a ambos enemigos con un Abisario o Súcubo (seduce a uno de ellos) y ve a despojar los planos."},linea=21590,filtro={{"c:WARLOCK"}}},{t="nota",texto={en="Build up 25+ rage, then fear all 3 mobs at the same time and click to loot the plans.",es="Acumula más de 25 de ira, luego aterroriza a los 3 enemigos al mismo tiempo y haz clic para despojar los planos."},linea=21591,filtro={{"c:WARRIOR"}}},{t="nota",texto={en="Go pull all 3 mobs and use your AOE fear to loot the plans.",es="Ve a tirar de los 3 enemigos y usa tu miedo de AoE para despojar los planos."},linea=21592,filtro={{"c:PRIEST"}}},{t="nota",texto={en="With improved gouge this is possible. Use Sap on one target, the prepare yourself near the plans. Use blind on a second target. Last one is the hard one, you have to use gouge (5.5 sec cd) and instantly start looting the plans (5 sec)",es="Con Gubia mejorada esto es posible. Usa Porrazo en un objetivo, luego prepárate cerca de los planos. Usa Cegar en un segundo objetivo. El último es el difícil, tienes que usar Gubia (5,5 s de reutilización) y empezar al instante a despojar los planos (5 s)"},linea=21593,filtro={{"c:ROGUE"}}},{t="nota",texto={en="Use Polymorph on Maltorius then frostnova the other 2 elites and blink to the plans and loot them.",es="Usa Polimorfia en Maltorius, luego Nova de escarcha a los otros 2 élites, parpadea hasta los planos y despójalos."},linea=21594,filtro={{"c:MAGE"}}},{t="nota",texto={en="After looting the plans, jump down below to the main floor OR the ledge to the right of the plans to evade any mobs you have aggro of",es="Después de despojar los planos, salta abajo al piso principal O a la cornisa a la derecha de los planos para evadir a los enemigos que te tengan en su lista de amenaza"},linea=21595},{t="complete",objetivo=1,q=7722,linea=21596}},requisitos={{t="paso",etiqueta="caught"},{t="elite",filtro={{"c:MAGE"}}}},linea=21585},{id="6c9ceac8",n=44,etiquetas={label="dwarves"},elementos={{t="goto",mapa=1427,x=45.23,y=38.41,modo="paso",radio=60,linea=21599},{t="goto",mapa=1427,x=47.53,y=24.87,modo="flecha",linea=21600},{t="nota",texto={en="Jump down to the lower level. Kill Incendosaurs",es="Salta al nivel inferior. Mata Incendosaurios"},linea=21601},{t="complete",objetivo=1,q=7727,linea=21602}},requisitos={},linea=21597},{id="77289215",n=45,etiquetas={completewith="end"},elementos={{t="deathskip",texto={en="Die and respawn at Thorium Point",es="Muere y reaparece en Punta de Torio"},linea=21611}},requisitos={},linea=21608},{id="8f9f8ca4",n=46,etiquetas={label="end"},elementos={{t="target",npcs={{nombre="Hansel Heavyhands",id=14627}},linea=21614},{t="nota",texto={en="|Tinterface/worldmap/chatbubble_64grey.blp:20|tTalk to |cRXP_FRIENDLY_Hansel Heavyhands|r",es="|Tinterface/worldmap/chatbubble_64grey.blp:20|tHabla con |cRXP_FRIENDLY_Hansel Manospesadas|r"},linea=21615},{t="turnin",q=7727,texto={en="Turn in Incendosaurs? Whateverosaur is More Like It",es="Entrega la misión ¿Incendosaurio? Loqueseasaurio más bien"},linea=21616},{t="goto",mapa=1427,x=38.58,y=27.8,modo="flecha",padre=2,linea=21617},{t="target",npcs={{nombre="Taskmaster Scrange",id=14626}},linea=21618},{t="nota",texto={en="|Tinterface/worldmap/chatbubble_64grey.blp:20|tTalk to |cRXP_FRIENDLY_Taskmaster Scrange|r",es="|Tinterface/worldmap/chatbubble_64grey.blp:20|tHabla con |cR